codeExample.bad:
// A custom modal that captures Tab but never lets it leave
modal.addEventListener('keydown', (event) => {
  if (event.key === 'Tab') {
    event.preventDefault();
    focusNextElementInside(modal);
  }
  // No handling for Escape, and focus is never released
});

codeExample.good:
// The modal cycles Tab focus within itself (a valid pattern) but
// provides a documented, working way out via Escape
modal.addEventListener('keydown', (event) => {
  if (event.key === 'Tab') {
    event.preventDefault();
    focusNextElementInside(modal);
  }
  if (event.key === 'Escape') {
    closeModal();
    triggerButton.focus();
  }
});
